import os
from typing import Any, Dict, List

import boto3


def extract_document_layout(file_path: str) -> Dict[str, List[Dict[str, Any]]]:
    textract = boto3.client(
        "textract",
        region_name=os.getenv("AWS_REGION", "us-east-1"),
    )

    with open(file_path, "rb") as f:
        document_bytes = f.read()

    response = textract.analyze_document(
        Document={"Bytes": document_bytes},
        FeatureTypes=["TABLES", "FORMS", "LAYOUT"],
    )

    blocks = response.get("Blocks", [])
    by_id = {block["Id"]: block for block in blocks if "Id" in block}

    result = {
        "pages": [],
        "lines": [],
        "tables": [],
        "cells": [],
        "key_value_sets": [],
        "layout_elements": [],
        "words": [],
    }

    for block in blocks:
        block_type = block.get("BlockType")
        item = {
            "id": block.get("Id"),
            "type": block_type,
            "text": block.get("Text"),
            "confidence": block.get("Confidence"),
            "page": block.get("Page"),
            "geometry": block.get("Geometry"),
            "entity_types": block.get("EntityTypes", []),
            "row_index": block.get("RowIndex"),
            "column_index": block.get("ColumnIndex"),
            "row_span": block.get("RowSpan"),
            "column_span": block.get("ColumnSpan"),
            "selection_status": block.get("SelectionStatus"),
            "relationships": block.get("Relationships", []),
        }

        if block_type == "PAGE":
            result["pages"].append(item)
        elif block_type == "LINE":
            result["lines"].append(item)
        elif block_type == "WORD":
            result["words"].append(item)
        elif block_type == "TABLE":
            table_cells = []
            for rel in block.get("Relationships", []):
                if rel.get("Type") == "CHILD":
                    for child_id in rel.get("Ids", []):
                        child = by_id.get(child_id, {})
                        if child.get("BlockType") == "CELL":
                            table_cells.append(child_id)
            item["cell_ids"] = table_cells
            result["tables"].append(item)
        elif block_type == "CELL":
            result["cells"].append(item)
        elif block_type == "KEY_VALUE_SET":
            result["key_value_sets"].append(item)
        elif block_type and block_type.startswith("LAYOUT_"):
            result["layout_elements"].append(item)

    return result
